+++ b/bin/greet.mjs
@@ -1,11 +1,14 @@
 #!/usr/bin/env node
 // greet: prints a friendly greeting.
-// Usage: greet [name]
+// Usage: greet [name] [--shout]
 export function greet(name = 'world') {
   return `Hello, ${name}!`;
 }

 if (import.meta.url === `file://${process.argv[1]}`) {
   const args = process.argv.slice(2);
-  console.log(greet(args[0]));
+  const shout = args.includes('--shout');
+  const name = args.filter((arg) => arg !== '--shout')[0];
+  const greeting = greet(name);
+  console.log(shout ? greeting.toUpperCase() : greeting);
 }
diff --git a/test/greet.test.mjs b/test/greet.test.mjs
index 1d70468..a8ae377 100644
--- a/test/greet.test.mjs
+++ b/test/greet.test.mjs
@@ -1,7 +1,12 @@
 import { test } from 'node:test';
 import assert from 'node:assert/strict';
+import { execFileSync } from 'node:child_process';
+import { fileURLToPath } from 'node:url';
 import { greet } from '../bin/greet.mjs';

+const cli = fileURLToPath(new URL('../bin/greet.mjs', import.meta.url));
+const runCli = (...args) => execFileSync(process.execPath, [cli, ...args], { encoding: 'utf8' });
+
 test('greets the world by default', () => {
   assert.equal(greet(), 'Hello, world!');
 });
@@ -9,3 +14,20 @@ test('greets the world by default', () => {
 test('greets a name', () => {
   assert.equal(greet('Mike'), 'Hello, Mike!');
 });
+
+test('CLI shouts the default greeting', () => {
+  assert.equal(runCli('--shout'), 'HELLO, WORLD!\n');
+});
+
+test('CLI shouts a name before the flag', () => {
+  assert.equal(runCli('Mike', '--shout'), 'HELLO, MIKE!\n');
+});
+
+test('CLI shouts a name after the flag', () => {
+  assert.equal(runCli('--shout', 'Mike'), 'HELLO, MIKE!\n');
+});
+
+test('CLI preserves ordinary greetings', () => {
+  assert.equal(runCli(), 'Hello, world!\n');
+  assert.equal(runCli('Mike'), 'Hello, Mike!\n');
+});
